from __future__ import annotations

import logging

_litellm_configured = False


def configure_litellm_for_rasa() -> None:
    """Configures LiteLLM for use within Rasa.

    Suppresses print()-based debug footers (for example, provider-list hints) by
    setting ``litellm.suppress_debug_info`` to ``True``, and sets the
    ``LiteLLM`` logger level to ``WARNING``. Idempotent: only the first call
    applies these settings.
    """
    global _litellm_configured
    if _litellm_configured:
        return

    import litellm

    litellm.suppress_debug_info = True
    logging.getLogger("LiteLLM").setLevel(logging.WARNING)
    _litellm_configured = True
